from depth import *

Lecture('building-media',[
Q('field','Полевой уровень автоматизации','В здании нужно различать измерение, принятие решения и физическое воздействие. Экран диспетчера показывает состояние, но сам по себе не объясняет, где выполняется управление.',[
 O(1),S('Датчик и исполнительный механизм','Датчик преобразует наблюдаемую величину в сигнал; исполнительный механизм изменяет физическое состояние: положение клапана, скорость вентилятора или освещение. Контроллер связывает измерение, заданное значение и разрешённое воздействие.','Для учебного контура температуры покажите два направления: температура поступает к контроллеру, команда идёт к приводу. Обратная связь о положении привода отличается от самой команды. Если команда отправлена, это ещё не доказывает её выполнение.'),E('Команда и подтверждённое состояние','Учебный привод получил команду «открыть 50%», но обратная связь показывает 0%, а датчик расхода не изменился. Подтверждена выдача команды; достижение состояния не подтверждено.','Проверяют разрешения, режим привода, питание и канал обратной связи по разрешённому регламенту. Нельзя повторять команды бесконечно или объявлять привод исправным по записи на экране.')],Check('Команда отправлена, положение не изменилось. Что подтверждено?', ['Физическое действие выполнено','Только выдача команды; нужно проверить фактическое состояние','Датчик обязательно сломан'],1,'Выдача команды и обратная связь — независимые наблюдения; причина ещё не локализована.'),'Полевой контур различает измерение, команду и подтверждённое физическое состояние.'),
Q('controllers','Контроллер, диспетчеризация и события','Локальный контроллер может выполнять алгоритм без открытого диспетчерского экрана. Разберём, что добавляет верхний уровень и какие зависимости нужно учитывать.',[
 S('Локальный алгоритм и верхний уровень','Контроллер выполняет заданную логику контура; диспетчеризация показывает значения, события и разрешённые команды оператора. Потеря верхнего уровня не обязательно означает остановку локального алгоритма — это определяется проектом системы.','В паспорте фиксируют автономные функции и зависимые команды. Учебный оператор не меняет алгоритмы работающего здания ради проверки. Поведение при потере связи изучают на стенде либо по утверждённой документации и наблюдаемым событиям.'),S('Значение, качество и время измерения','На экране нужны не только число и единица, но и время обновления и признак качества связи. Значение 22 °C, полученное час назад до потери канала, не доказывает текущую температуру.','Различайте «последнее известное значение» и «текущее измерение». При восстановлении связи проверьте смену времени и качества данных. Иначе интерфейс может создавать ложное впечатление нормальной работы.'),E('Порог и гистерезис','Учебное правило: включить охлаждение при температуре выше 25 °C, выключить ниже 23 °C, между порогами сохранить прежнее состояние. При 24 °C результат зависит от того, было ли охлаждение включено раньше.','Это два порога для предотвращения частого переключения около одной границы. Гистерезис не является таймером и не исправляет неисправный датчик. Проследите последовательность 26→24→22: включено, включено, выключено.',table(['Температура','Предыдущее состояние','Результат'],[['26 °C','Выключено','Включить'],['24 °C','Включено','Сохранить включение'],['22 °C','Включено','Выключить']],'Это учебный алгоритм; реальные уставки определяются проектом оборудования.'))],Check('По учебному правилу включение выше 25 °C, выключение ниже 23 °C. Было включено, стало 24 °C. Результат?', ['Выключить','Сохранить включение','Всегда включать и выключать одновременно'],1,'Температура между порогами; сохраняется предыдущее состояние.'),'Диспетчеризация показывает локальные контуры вместе с качеством и временем данных.'),
Q('media','Состав мультимедийного тракта','Перейдём от управления инженерией к передаче изображения и звука. Управляющая команда и медиасигнал проходят разными путями.',[
 O(2),S('Источник, коммутация и выход','Источник создаёт медиасигнал; коммутатор выбирает направление; обработка меняет формат или уровень; выходное устройство воспроизводит результат. Панель управления может отправлять команды этим узлам, не передавая сам звук или видео.','Если кнопка маршрута сработала, проверьте сигнал на входе, выбранный путь и физический выход. Рабочая панель управления не доказывает наличие контента. Схема должна показывать и управление, и медиатракт с разными подписями.'),E('Один источник, две зоны','Учебный проигрыватель подаёт звук в DSP; выход A идёт в зал, B — в коридор. Панель выбирает общий источник, но уровни и mute на выходах независимы.','Если B работает, наличие входного сигнала подтверждено для общего участка. Это направляет проверку A к его маршруту и выходу, хотя не доказывает автоматически неисправность усилителя.',process([('Источник','Общий аудиосигнал'),('DSP','Маршруты и уровни A/B'),('Зоны','Усилитель и громкоговорители')],'Общая часть и независимые выходы позволяют локализовать область проверки.'))],Check('Панель показывает выбранный источник, но на входе DSP нет сигнала. Что ещё не подтверждено?', ['Наличие самого медиасигнала','Наличие команды выбора','Факт изображения кнопки'],0,'Команда выбора относится к управлению; измерение входа проверяет медиатракт.'),'Медиасигнал и управление описывают как связанные, но разные тракты.'),
Q('zones','Зоны, приоритеты и уровни','Разделение на зоны позволяет независимо управлять направлением и уровнем. Оно требует явных правил приоритета и проверки безопасных пределов.',[
 O(3),S('Приоритет источников','Приоритет задаёт, какой разрешённый источник занимает выход при конкуренции. Возврат после окончания сообщения должен иметь определённое состояние: прежний источник, тишина или иной установленный режим.','Проверку выполняют на учебной медиасистеме с допустимыми уровнями. Работу систем безопасности и оповещения не изменяют как обычную настройку фоновой музыки. У них отдельные проектные и эксплуатационные требования.'),E('Проверка восстановления маршрута','Учебное правило: сообщение оператора временно прерывает музыку в зоне A, затем музыка возвращается; зона B не меняется. Проверка включает начало сообщения, конец и возврат A к прежнему маршруту.','Только начало прерывания не подтверждает весь сценарий. После завершения проверьте источник, уровень и mute в обеих зонах. Сохраняют исходную конфигурацию, чтобы оценивать изменение относительно неё.')],Check('Временное сообщение завершилось. Какая проверка нужна по заданному сценарию?', ['Только сообщение началось','Возврат музыки в A и сохранность состояния B','Увеличить громкость до предела'],1,'Сценарий включает и приоритетное воздействие, и возврат, и отсутствие изменения соседней зоны.'),'Зонный сценарий проверяют по входу, приоритету, выходу и восстановлению состояния.'),
Q('diagnostics','Диагностика сигнального тракта','Симптом «нет звука» не указывает на единственный компонент. Используем наблюдения на границах тракта и меняем по одному условию.',[
 O(4),S('Контрольные точки и локализация','Проверяют источник, входной индикатор, маршрут, выходной уровень, mute, усилитель и разрешённую нагрузку. Рабочий соседний выход подтверждает только общую часть, которую оба используют.','Не переподключайте сразу все кабели: исчезнет связь между действием и результатом. Сначала сохраните настройки и наблюдения. Подмена проверенным элементом имеет смысл, если она совместима и выполняется в разрешённом состоянии.'),E('Сравнение двух наблюдений','Случай A: вход DSP активен, B слышен, A на mute. Случай B: вход отсутствует, оба выхода молчат. В A первым проверяют состояние выхода A; в B — источник и общий входной участок.','Различие условий меняет маршрут диагностики. Указание «проверить источник» не универсально для любого отсутствия звука. После исправления оба случая завершают проверкой исходной программы и допустимого уровня.')],Check('Вход активен, B работает, A на mute. С чего начать проверку?', ['С подтверждения и снятия mute A в разрешённом режиме','С полной замены источника','С удаления всей конфигурации'],0,'Наблюдение локализует конкретное состояние A; несвязанные изменения пока не обоснованы.'),'Диагностика опирается на контрольные точки и изменение одного условия.'),
Q('maintenance','Эксплуатация и конфигурация','Система здания хранит адреса, уставки, маршруты и журнал изменений. Восстановление требует согласовать конфигурацию с реальным оборудованием.',[
 O(5),S('Копия конфигурации и паспорт','Сохраняют разрешённую копию конфигурации, состав узлов, версии, адреса, назначения портов и исходные уровни. Копия должна соответствовать конкретному комплексу; файл от похожего объекта может задавать неверные выходы.','После изменения отмечают, кто и что изменил, основание и результат проверки. Пароли и ключи доступа хранят отдельно в установленном защищённом порядке. Паспорт указывает способ доступа для ответственных, но не распространяет секреты.'),E('Проверка после замены узла','На учебном стенде заменён медиапроцессор. Проверяют загрузку согласованной конфигурации, соответствие физических портов, оба источника, каждую зону и возврат после временного сообщения.','Успешный вход в интерфейс подтверждает только управление узлом. Ошибка сопоставления портов может направить звук в другую зону. Поэтому проверка проходит по назначениям, а не по наличию сетевого адреса.')],Check('Новый процессор отвечает по сети. Что ещё нужно для приёмки замены?', ['Ничего','Проверить конфигурацию, назначения портов и все заданные зонные сценарии','Только изменить его имя'],1,'Адресная доступность не подтверждает правильный медиатракт и зонную логику.'),'Эксплуатация сохраняет конфигурацию, ответственность и проверенные сценарии всех зон.')
],[('Почему число на диспетчерском экране может быть недостоверным по времени?','Это может быть последнее известное значение до потери связи; нужны время и качество обновления.'),('Чем управляющий тракт отличается от медиатракта?','Первый передаёт команды, второй — звук или видео; успех команды не доказывает наличие сигнала.'),('Зачем после приоритетного сообщения проверять возврат?','Сценарий включает восстановление прежнего состояния и отсутствие изменений других зон.')],H('Нарисуйте учебный тракт: проигрыватель → DSP → усилители A и B → две зоны. Вход активен, B работает, A молчит; выход A показывает mute.','Отметьте контрольные точки, первое обоснованное действие и конечную проверку.','Сдайте схему с направлением медиасигнала и отдельно обозначенным управлением.','Сначала подтвердить mute A и разрешённое снятие; затем проверить звук A, прежний уровень и сохранность B. Полная замена источника не обоснована.'))

Lecture('integration',[
Q('groups','Роли оборудования интеграции','Комплекс соединяет разные виды оборудования и сигналов. Состав полезен только вместе с назначением каждого узла и его интерфейсов.',[
 O(1),S('Источник, приёмник и посредник','Источник формирует сигнал, приёмник воспроизводит или записывает, посредник коммутирует, распределяет либо преобразует. Один корпус может выполнять несколько ролей, поэтому схема опирается на конкретные входы и выходы.','Слово «адаптер» не объясняет преобразование. Установите направление, входной и выходной формат, питание и ограничения. Кабель с подходящими разъёмами не обязательно содержит нужное активное преобразование.'),E('Три независимых вопроса совместимости','Учебная пара: HDMI-источник и HDMI-дисплей. Совпадение разъёма ещё не проверяет поддерживаемый режим, требования защиты контента и допустимую длину линии.','Начинают с поддерживаемого общего режима и проверенного короткого соединения. Затем добавляют остальные элементы по одному. Это позволяет связать потерю изображения с конкретным участком, а не с общей фразой «HDMI не работает».')],Check('Совпали разъёмы источника и дисплея. Что ещё проверять?', ['Поддерживаемый формат и режим сигнала','Только цвет кабеля','Ничего: совместимость доказана'],0,'Механическая совместимость не гарантирует согласованный режим и корректный тракт.'),'Оборудование классифицируют по роли, типу сигнала и направлению интерфейса.'),
Q('switching','Коммутация и распределение','Коммутатор выбирает или распределяет связи. Различим коммутацию медиасигнала и пакетную передачу в локальной сети.',[
 S('Медиакоммутатор и матрица','Переключатель выбирает один из входов на выход; распределитель направляет один сигнал нескольким приёмникам; матрица задаёт несколько соответствий входов и выходов. Направления должны быть обозначены явно.','Для матрицы 2×2 запишите, какой источник назначен A и B. Если в обеих зонах один контент, это может быть штатным маршрутом, а не неисправностью. Фактическую конфигурацию сравнивают с требуемой таблицей.'),S('Сетевой коммутатор и PoE','Сетевой коммутатор передаёт кадры между портами. PoE добавляет питание совместимых устройств по линии Ethernet, но имеет ограничения отдельного порта и общего бюджета. Коммутация данных и подача питания проверяются раздельно.','Сумма паспортных потреблений даёт первоначальную оценку. Дополнительно сверяют режим, пусковые требования и доступный бюджет конкретного устройства. Наличие сетевого разъёма камеры не доказывает совместимость её питания.'),O(4)],Check('Четыре камеры по 12 Вт, бюджет PoE 45 Вт. Какой вывод следует только из этих данных?', ['48 Вт превышают общий бюджет','Каждая камера потребляет 3 Вт','Достаточно любого кабеля','Работа гарантирована'],0,'Сумма 4×12=48 Вт больше 45 Вт. Ограничения портов и совместимость проверяются дополнительно.'),'Для коммутации проверяют маршрут данных; для PoE — совместимость, порт и общий бюджет.'),
Q('display','Отображение информации','Дисплей является конечной точкой тракта, но неисправность картинки может возникнуть раньше. Уточним режим и направление соединения.',[
 S('Видеорежим и выбор входа','Источник и приёмник должны поддерживать общий режим: разрешение, частоту и другие параметры интерфейса. На дисплее выбирают физически подключённый вход. Соединение OUT источника → IN дисплея фиксируют на схеме.','Проверяют один известный источник, исправный кабель и совместимый режим. Если встроенное меню дисплея видно, это подтверждает часть его работы, но не наличие внешнего сигнала. Переключение на нужный IN — отдельное действие.'),E('Читаемость — часть результата','Учебный экран показывает таблицу в полном разрешении, но подписи с последнего ряда не читаются. Сигнал передаётся, однако функция отображения для аудитории не выполнена.','Уточняют размер текста, масштаб, расстояние и контраст. Повышение разрешения само по себе может уменьшить интерфейсные элементы. Итог проверяют на месте предполагаемого просмотра, а не только рядом с экраном.')],Check('Меню дисплея видно, внешний сигнал нет. Что подтверждено?', ['Внешний видеотракт полностью исправен','Дисплей способен показать своё меню; внешний вход и тракт ещё проверяются','Источник обязательно сломан'],1,'Встроенное меню не проходит через внешний кабель и источник.'),'Проверка отображения включает вход, режим, сигнал и читаемость в месте использования.'),
Q('audio','Звуковое оборудование','Звуковой тракт включает источники, уровни, обработку, усиление и нагрузку. Согласование выполняется по документации конкретных устройств.',[
 S('Линейный сигнал и выход усилителя','Линейный выход передаёт сигнал на вход обработки или усиления. Выход усилителя предназначен для соответствующей акустической нагрузки. Одинаковый вид разъёма не разрешает соединять любые уровни.','Перед подключением определяют назначение порта, уровень и требования нагрузки. Учебная схема не заменяет инструкцию производителя. Ошибку уровня нельзя исправлять случайным повышением громкости на всех узлах.'),S('Уровень, перегрузка и mute','Наличие входного сигнала, допустимый уровень и отсутствие mute — разные условия. Перегрузка может искажать звук при формально работающем тракте. Слишком низкий вход и последующее чрезмерное усиление увеличивают слышимость помех.','Проверяют по контрольным точкам с допустимым тестовым уровнем. Индикатор clip указывает на конкретную ступень; его наличие не объясняется просто «плохими колонками». После исправления убеждаются в отсутствии перегрузки по всему тракту.'),E('Локализация искажения','Учебные наблюдения: на входе DSP уровень допустим, на выходе DSP нет перегрузки, clip усилителя срабатывает. В первую очередь проверяют настройки и нагрузку ступени усиления в разрешённых пределах.','Это направление проверки, а не окончательный диагноз усилителя. Если clip возникает уже на входе DSP, область причины меняется. Условия и показания нужно сохранить до изменения настроек.')],Check('Вход DSP уже перегружен. Поможет ли только уменьшение громкости после DSP убрать исходное искажение?', ['Да, всегда','Нет: нужно устранить перегрузку там, где она возникла','Нужно отключить журнал'],1,'Позднее ослабление делает искажённый сигнал тише, но не восстанавливает утраченную форму.'),'Звук проверяют по назначению портов, уровням и месту возникновения перегрузки.'),
Q('surveillance','Камеры, регистратор и архив','Видеонаблюдение одновременно передаёт, записывает и воспроизводит данные. Успех одного действия не гарантирует остальные.',[
 S('Поток и запись','IP-камера формирует поток; сеть доставляет его; регистратор или сервис записи сохраняет архив; клиент запрашивает просмотр. Живое изображение может работать при остановленной записи или переполненном накопителе.','Для проверки архива создают допустимое тестовое событие с известным временем, затем находят и воспроизводят его. Вход в меню регистратора и индикатор камеры являются промежуточными проверками.'),E('Оценка объёма архива','Учебная постоянная суммарная скорость — 8 Мбит/с. За сутки: 8/8=1 МБ/с; 1×86400=86400 МБ, то есть 86,4 ГБ в десятичных единицах. За 7 суток — 604,8 ГБ без накладных расходов.','Указаны постоянный битрейт и десятичные единицы. Реальный поток может меняться, а полезное место меньше номинального. Не смешивайте Мбит/с и МБ/с; это даёт восьмикратную ошибку.'),O(5)],Check('Суммарный поток 8 Мбит/с. Какова скорость в МБ/с при 8 битах в байте?', ['1','8','64','0,125'],0,'8 Мбит/с ÷ 8 = 1 МБ/с. Накладные расходы в учебной оценке не учитываются.'),'Видеонаблюдение принимают по живому потоку и воспроизведению нужного фрагмента архива.'),
Q('ports','Интерфейсы и схема соединений','Чтобы воспроизвести подключение, нужны не только блоки, но и порты, направления, типы линий и питание.',[
 O(3),S('Таблица соединений','Для каждой линии записывают источник и порт, приёмник и порт, тип сигнала, кабель или канал и назначение. Питание обозначают отдельной связью, если оно не входит в согласованный интерфейс.','Надпись «компьютер — экран» не сообщает, куда включить кабель. Таблица помогает сверить физическое подключение с логической схемой. Номера портов должны совпадать с маркировкой на реальном комплекте.'),O(2)],Check('Какая запись позволяет повторить подключение?', ['Ноутбук связан с дисплеем','Ноутбук HDMI OUT → дисплей HDMI IN 1, кабель HDMI, видеосигнал','Дисплей красивый'],1,'Запись задаёт оба порта, направление и тип сигнала.'),'Схема подключения должна быть воспроизводима по портам, направлениям и назначению линий.'),
Q('acceptance','Проверка интегрированного комплекса','Приёмка комплекса возвращается к пользовательскому сценарию. Каждый тракт и их совместная работа должны соответствовать выбранному назначению.',[
 S('Проверка по одному изменению','Фиксируют исходный маршрут и контрольный источник; проверяют питание, связь, режим, вход и выход. Затем добавляют обработку и управление. После каждого изменения записывают наблюдаемый результат.','Такой порядок не является универсальной последовательностью для любого производителя, но сохраняет причинность учебного эксперимента. Одновременная замена трёх элементов позволяет восстановить работу, не объяснив причину.'),E('Сценарий переговорной','Учебная цель: показать ноутбук на дисплее, воспроизвести его звук через разрешённый тракт и сохранить тестовый фрагмент камеры. Проверка включает выбор входа, читаемость, звук без перегрузки и поиск записи по времени.','Успех видео не закрывает звук и архив. В акте фиксируют каждый результат и ограничения: например, внешний удалённый участник не участвовал в тесте, поэтому сетевую конференцию не объявляют проверенной.')],Check('Проверены изображение и звук, архив не воспроизводился. Как оформить результат?', ['Весь комплекс полностью проверен','Изображение и звук проверены; запись и воспроизведение остаются непроверенными','Удалить сведения о тесте'],1,'Объём вывода должен соответствовать выполненным действиям.'),'Приёмка фиксирует фактически проверенные тракты и сквозные сценарии.')
],[('Почему камера с живым изображением может не иметь архива?','Передача и запись выполняются разными частями; нужны место, расписание, время и работающая служба записи.'),('Чем таблица портов дополняет блоковую схему?','Она задаёт конкретные концы, направление, тип сигнала и позволяет повторить подключение.'),('Как локализовать перегрузку аудио?','Наблюдать уровни по ступеням и исправлять источник перегрузки, а не только ослаблять поздний выход.')],H('Для 3 камер задан постоянный поток по 4 Мбит/с. Срок хранения 2 суток; накладные расходы в учебной оценке не учитываются.','Переведите суммарную скорость в МБ/с и вычислите десятичные ГБ. Отдельно перечислите, чего не хватает для выбора реального накопителя.','Сдайте расчёт с единицами и план проверки записи и воспроизведения.','12 Мбит/с = 1,5 МБ/с; 1,5×172800=259200 МБ=259,2 ГБ. Нужны полезная ёмкость, запас, режим потока и требования хранения.'))

Lecture('lan',[
Q('topology','Топология и границы локальной сети','Сначала покажем, какие узлы соединены и какие элементы у них общие. Схема сети должна помогать определять масштаб отказа.',[
 O(1),S('Физическая и логическая схема','Физическая схема показывает кабели, порты и устройства. Логическая — подсети, VLAN, шлюзы и разрешённые пути. Одинаковая физическая звезда может поддерживать несколько изолированных логических сетей.','По одному рисунку кабелей нельзя заключить, что любые два узла обмениваются данными. Для этого нужны адреса и правила. При обслуживании связывают логическое имя порта с его физической маркировкой.'),E('Общий коммутатор и область отказа','Учебные АРМ-1 и АРМ-2 подключены к SW-1, сервер — к SW-2; коммутаторы соединены uplink. При разрыве uplink оба АРМ теряют сервер, но могут сохранять обмен между собой.','Наблюдение соответствует общей линии, но не доказывает именно обрыв: похожую картину даст неправильная логическая настройка пути. Проверяют состояние и конфигурацию конкретных портов.')],Check('Два АРМ видят друг друга, сервер за другим коммутатором недоступен. Где искать общую область проверки?', ['Только клавиатура каждого АРМ','Межкоммутаторный путь и его логическая конфигурация','Только разрешение экрана'],1,'Локальный обмен и общий отказ удалённого ресурса выделяют общий участок, но причина требует проверки.'),'Топология показывает связи и общие элементы, а логическая схема — условия обмена.'),
Q('switches','Активное оборудование','Различим функции устройств. Коммутатор, маршрутизатор и точка доступа решают разные задачи, хотя могут находиться в одном корпусе.',[
 S('Коммутатор и таблица MAC','Коммутатор обучается соответствию MAC-адресов входным портам и передаёт кадры внутри логического сегмента. Он не выбирает произвольный IP-шлюз для приложения. Поведение при неизвестном адресе отличается от передачи по известному порту.','Для эксплуатационной проверки достаточно понимать роль порта и сегмента. Не очищайте таблицы и не меняйте VLAN без основания. Сначала сравните фактическую конфигурацию с утверждённой схемой.'),S('Маршрутизатор и точка доступа','Маршрутизатор соединяет IP-сети по таблице маршрутов; точка доступа связывает беспроводных клиентов с сетью в принятой конфигурации. Успешное подключение к Wi-Fi не гарантирует получение подходящего адреса и доступа к серверу.','Устройство домашнего типа может совмещать маршрутизацию, Wi-Fi и коммутатор, но роли по-прежнему различаются. В корпоративной сети нельзя подключать случайный дополнительный DHCP-сервер как способ «починить адреса».'),E('Подключение к чужому сегменту','Учебный АРМ переставили в порт гостевой VLAN. Link есть, адрес получен, интернет работает, внутренний APP-01 недоступен. Это не противоречие: разрешённый путь к внутреннему сервису отсутствует по конфигурации.','Сначала проверяют назначение порта и право АРМ находиться в рабочем сегменте. Отключение фильтрации целиком не является обоснованным исправлением.')],Check('Есть Wi-Fi и интернет, внутренний сервер недоступен. Что ещё нужно проверить?', ['Сегмент, адресацию и разрешённый маршрут к серверу','Только значок Wi-Fi','Сразу отключить все ограничения'],0,'Доступ к интернету и внутреннему ресурсу использует разные условия и пути.'),'Функции активных устройств и логическое назначение портов учитывают раздельно.'),
Q('address','IP-адрес и префикс','Адрес без префикса не определяет локальный сетевой диапазон. Разберём простую подсеть и границы доступных адресов.',[
 O(2),S('Учебная подсеть /24','Для 192.168.10.0/24 сетевой адрес — .0, широковещательный — .255; обычные адреса узлов — .1–.254. Префикс /24 соответствует маске 255.255.255.0. Эти правила относятся к указанному IPv4-примеру.','Число 254 — адресная ёмкость этой подсети до резервов и назначений, а не разрешённое число новых АРМ. Часть адресов уже занята. Для /31 и /32 действуют особые контексты, поэтому нельзя переносить эту памятку на любой префикс.'),E('Ошибка префикса меняет выбор пути','Учебный АРМ 192.168.10.18/24 обращается к серверу 192.168.11.20: нужен маршрут через шлюз. Если ошибочно поставить /16, АРМ будет считать сервер локальным и искать его напрямую в своём канальном сегменте.','Это объясняет, почему неверная маска может нарушить доступ при внешне похожем адресе. Исправляют по утверждённому плану адресации, затем проверяют путь. Случайная смена нескольких параметров скрывает причину.')],Check('Для 192.168.10.18/24 сервер 192.168.11.20 находится где?', ['В той же /24 подсети','В другой IP-подсети; нужен разрешённый маршрут','Адрес сервера запрещён всегда'],1,'При /24 различается третий октет сети: 10 и 11. Нужен маршрут между сетями.'),'Префикс определяет сетевую часть адреса и выбор локального либо маршрутизируемого пути.'),
Q('services','Шлюз, DNS и получение адреса','Успешный IP-обмен не гарантирует работу по имени. Разделим параметры, которые часто смешиваются в одном окне настройки.',[
 S('Шлюз по умолчанию','Шлюз используется для назначения вне непосредственно подключённых сетей при отсутствии более точного маршрута. Для обмена двух обычных узлов одной подсети он не обязан участвовать. Шлюз должен быть достижим по соответствующему локальному пути.','Проверка локального сервера не подтверждает правильность шлюза. Поэтому фраза «сеть работает» требует названного назначения. У учебного узла могут быть разные результаты для соседнего АРМ и удалённого филиала.'),S('DNS и DHCP','DNS сопоставляет имена с данными, в том числе адресами. DHCP может выдавать клиенту адрес, префикс, шлюз и DNS по заданной конфигурации. Автоматическое получение не означает, что выданные параметры соответствуют нужному сегменту.','Сохраняют фактические параметры и сравнивают с планом. Если имя разрешилось в старый адрес, сначала проверяют источник и актуальность записи. Очистка кэша без исправления ошибочного источника может дать лишь временное наблюдение.'),E('Локальный ресурс без шлюза','Учебный АРМ 192.168.10.18/24 и сервер .20/24 находятся в одном разрешённом сегменте; шлюз на АРМ не задан. Это само по себе не запрещает их локальный обмен, но доступ в другую подсеть потребует маршрута.','Если .20 недоступен, отсутствие шлюза не является достаточным объяснением в данных условиях. Продолжают проверку канала, адресов, фильтрации и сервиса.')],Check('Два узла одной /24 подсети, один без шлюза. Какой вывод корректен?', ['Локальный обмен невозможен при любых условиях','Отсутствие шлюза само по себе не объясняет отказ локального обмена','DNS всегда заменяет шлюз'],1,'Шлюз требуется для соответствующего нелокального пути, а не для всякого обращения внутри подсети.'),'Адрес, префикс, шлюз, DNS и DHCP имеют разные роли и проверяются по назначению.'),
Q('checks','Состав проверок персонала','Персонал начинает с безопасного сбора фактов и проверки разрешённой функции. Команды должны отвечать на конкретный диагностический вопрос.',[
 O(3),S('Читающие проверки Windows','На разрешённом учебном АРМ ipconfig /all показывает конфигурацию, ping проверяет доступные ICMP-ответы, Resolve-DnsName — разрешение имени, Test-NetConnection с -Port — TCP-соединение. Вывод каждой команды имеет ограниченный смысл.','Сохраняйте команду, время, адрес и результат. Не требуйте одинакового ответа ping от устройств, где ICMP фильтруется. Успешное TCP-соединение не подтверждает правильные права и сохранение документа.'),E('Порт доступен, операция запрещена','Учебная проверка Test-NetConnection APP-01 -Port 443 успешна. Приложение отклоняет проведение из-за отсутствующей роли. Транспортная доступность подтверждена, разрешённое предметное действие — нет.','Нужно проверить назначение пользователя и журнал отказа. Изменение IP-адреса не даёт полномочие. После согласованного назначения роли проверяют всю операцию.')],Check('TCP-порт 443 доступен. Что этим не доказано?', ['Установление TCP-соединения в момент теста','Право пользователя провести документ','Достижимость указанного TCP-порта'],1,'TCP-проверка не выполняет авторизацию и предметную операцию.'),'Каждая команда подтверждает определённый уровень; итог проверяют приложением.'),
Q('faults','Типовые неисправности и проверка гипотез','Сопоставим симптомы с конкретными параметрами. Диагностика должна уменьшать неопределённость, а не случайно менять настройки.',[
 O(4),O(5),E('Проверка гипотезы по одному изменению','Учебный APP-01 разрешается в .30 вместо утверждённого .20. До изменения сохраняют результат запроса имени; после разрешённого исправления проверяют .20, TCP-порт и тестовую операцию.','Если имя стало правильным, но сервис остановлен, первая неисправность устранена, а цель ещё не достигнута. Такой результат нужно записать явно. Одна найденная причина не запрещает существование следующей.')],Check('Имя исправлено, но нужный TCP-порт закрыт. Каков статус?', ['Вся система восстановлена','Разрешение имени исправлено; доступность сервиса ещё не подтверждена','Нужно вернуть ошибочное имя'],1,'Проверка продвинулась на один уровень; требуемая функция пока не подтверждена.'),'Гипотезу проверяют наблюдением до и после одного обоснованного изменения.'),
Q('records','Регламент и документирование сети','Результат обслуживания должен быть воспроизводим другим сотрудником. Завершим составом записи и границами допустимых действий.',[
 S('План адресации и маркировка','План связывает имя узла, адрес, префикс, VLAN, порт, роль и ответственного. Статические адреса и диапазоны выдачи DHCP согласуют, чтобы исключить случайное пересечение. Фактические назначения отмечают после подтверждённого изменения.','Дубликат адреса нельзя устранять выбором первого «свободного на вид» числа. Адрес может принадлежать выключенному оборудованию. Проверяют реестр и порядок выделения, затем выполняют контрольную проверку.'),E('Запись о восстановлении','Учебная запись: время; АРМ и порт; симптом; исходные IP/DNS; проверка имени; согласованное исправление; результаты TCP и приложения; исполнитель. Секреты и лишние данные не включаются.','Фраза «починил сеть» не даёт следующей смене основания для проверки. Конкретные назначения и результаты отделяют от предположений: «порт недоступен» — наблюдение, «служба остановлена» требует дополнительного подтверждения.')],Check('Какой адрес можно назначить при конфликте?', ['Любой, который сейчас не отвечает на ping','Выделенный по утверждённому плану после проверки назначения','Любой адрес .0'],1,'Отсутствие ответа ping не доказывает, что адрес свободен; назначение должно быть согласовано.'),'Эксплуатационная запись связывает разрешённое изменение с планом сети и конечной проверкой.')
],[('Почему успешный ping не закрывает проверку ИС?','Он не подтверждает TCP, авторизацию, правила приложения и сохранение результата.'),('Когда отсутствие шлюза не объясняет отказ?','При обмене обычных узлов одной подсети в одном разрешённом сегменте.'),('Что нужно записать до изменения неправильного DNS?','Фактические параметры, результат разрешения, утверждённое назначение, время и симптом.')],H('Учебный АРМ 192.168.10.18/24, сервер 192.168.10.20/24. Имя APP-01 разрешается в .30; по .20 тестовая страница доступна.','Составьте порядок читающих проверок и критерий восстановления. Не назначайте новые адреса без плана.','Представьте наблюдения по IP, имени, порту и приложению отдельными строками.','Наблюдения выделяют ошибочное разрешение имени; после согласованного исправления проверяют правильный адрес, порт и сквозную операцию.'))

Lecture('documentation',[
Q('set','Назначение и комплект документации','Документация связывает состав системы, порядок работы и доказательства изменений. Начнём с того, какие вопросы закрывает каждый документ.',[
 O(1),S('Пользовательские и эксплуатационные документы','Пользовательская инструкция описывает предметную работу; эксплуатационная — поддержание и восстановление; схемы — структуру и связи; журнал — фактически выполненные события. Один документ может ссылаться на другой, но не подменять его назначение.','Краткая памятка оператора не должна содержать случайные административные команды. И наоборот, схема без порядка безопасного восстановления не является инструкцией. Комплект определяют по потребностям конкретной системы и принятому порядку организации.'),E('Поиск ответа в комплекте','Учебные вопросы: где подключён регистратор; кто подтверждает выдачу; что изменили вчера; как проверить восстановление. Ответы находятся соответственно в схеме, ролях и инструкции, журнале изменений, эксплуатационной процедуре.','Если всё записано в переписке одного сотрудника, комплект фактически недоступен смене. Проверьте, что документы можно найти и что указан их ответственный. Это эксплуатационный тест, а не только перечень файлов.')],Check('Какой документ прежде всего подтверждает, что именно изменили вчера?', ['Планируемая схема без отметок','Журнал выполненных изменений','Обложка инструкции'],1,'Журнал фиксирует событие, исполнителя и результат. План не доказывает выполнение.'),'Документы различают по вопросу, на который они дают проверяемый ответ.'),
Q('passport','Паспорт информационной системы','Паспорт представляет фактический состав и основные параметры. Его полезность определяется точностью связей с реальными объектами.',[
 O(2),S('Идентификатор, роль и состояние','Для объекта паспорта фиксируют устойчивый идентификатор, назначение, размещение, существенные параметры, ответственного и источник проверки. Неизвестные сведения отмечают как неподтверждённые, а не заполняют похожими значениями.','Имя DB-01 и серийный номер корпуса описывают разные уровни. В виртуальной среде нужно связать гостевую систему с физическим узлом. У одного объекта могут быть разные владельцы предметных данных и технического сопровождения.'),E('Строка паспорта с пробелом','Учебная строка: BAK-01, резервное копирование, место известно, адрес не подтверждён, восстановление не проверено. Это один объект с двумя пробелами, а не два отсутствующих устройства.','Паспорт должен сохранять различие между наличием компонента и подтверждением его функции. Назначение «копии» не доказывает успешное восстановление. Для каждой неизвестной характеристики назначают способ уточнения.',table(['Поле','Значение','Статус'],[['Объект','BAK-01','Подтверждён'],['Адрес','Не установлен','Уточнить по конфигурации'],['Восстановление','Не выполнено','Нужно разрешённое испытание']],'Неподтверждённое значение не заменяют вымышленным адресом.'))],Check('Адрес BAK-01 неизвестен. Что записать?', ['Любой адрес похожего сервера','Не подтверждён; указать источник и действие уточнения','Удалить объект из паспорта'],1,'Честно обозначенный пробел позволяет его закрыть, а выдуманный адрес делает документ опасно недостоверным.'),'Паспорт отражает фактические объекты, параметры и статус подтверждения сведений.'),
Q('schemes','Структурные и соединительные схемы','Разные схемы отвечают на разные вопросы. Для воспроизведения подключения недостаточно общего рисунка компонентов.',[
 O(3),S('Структура, соединения и размещение','Структурная схема показывает роли и связи; схема соединений — конкретные порты и линии; схема размещения — где находятся объекты. План адресации описывает логические назначения сети. Между документами сохраняют одинаковые идентификаторы.','Если SW-01 на схеме соединений назван иначе в паспорте, сотруднику придётся угадывать. Согласованная маркировка позволяет перейти от функции к корпусу и порту. Для одного устройства не создают новые имена только из-за другого вида схемы.'),E('Линия, которую можно проверить','Запись «APP-01 NIC1 → SW-01 port 8, VLAN 10» указывает конкретные концы и логическое назначение. Линия «сервер — сеть» показывает связь, но не позволяет восстановить физическое подключение.','В реальном комплекте дополнительно нужны применимый тип кабеля и маркировка трассы. Изменение порта может потребовать обновить и VLAN-план, и схему, и паспорт. Сначала устанавливают фактическую конфигурацию.')],Check('Как обеспечить связь схемы с паспортом?', ['Использовать разные имена для красоты','Сохранить общие идентификаторы объектов и сверить порты','Убрать все номера'],1,'Единые идентификаторы позволяют сопоставить уровни документации.'),'Виды схем дополняют друг друга и используют согласованную маркировку.'),
Q('instructions','Инструкция как воспроизводимая процедура','Инструкция должна начинаться с доступного исходного состояния. Успех последней команды сам по себе не подтверждает цель процедуры.',[
 S('Исходное состояние и разрешённые действия','В начале указывают роль исполнителя, среду, нужные данные, подготовку и допустимые границы. Затем — действие, ожидаемый результат и проверку. Для расхождения задают остановку или передачу ответственному.','Поручение «откройте подготовленный сервис» неполно, если не сказано, где он находится и кто его подготовил. Исполнитель должен понимать первое действие без чужого неописанного шага. Команды, меняющие рабочие данные, отделяют от читающих проверок.'),S('Ветвь отказа и возврат','Процедура описывает не только нормальный результат, но и действие при несовпадении: сохранить вывод, остановить опасное продолжение, обратиться к назначенному ответственному. Для изменения предусматривают согласованный возврат и конечную проверку.','Нельзя механически продолжать инструкцию после ошибки предыдущего шага, если дальнейшее действие использует его результат. Например, копирование не в ту целевую папку делает последующую проверку файла бессмысленной для нужной системы.'),E('Исправление неполной инструкции','Исходная фраза: «проверьте архив». Учебное уточнение: выбрать тестовую камеру, создать разрешённое событие в указанное время, дождаться записи, найти интервал и воспроизвести его; сохранить наблюдение и границы доступа.','Исправление добавило объект, данные, действие и признак успеха. Просмотр живого потока исключается как достаточное доказательство. Если нужного фрагмента нет, проверка фиксирует отказ, а не заменяется соседним днём.')],Check('Инструкция просит использовать файл, который нигде не предоставлен. Как оценить её?', ['Полностью воспроизводима','Есть пробел исходного состояния; нужно указать источник и подготовку файла','Исполнитель должен догадаться'],1,'Неописанный обязательный ресурс делает первое действие невыполнимым.'),'Инструкция задаёт исходное состояние, действие, результат, отказ и конечную проверку.'),
Q('changes','Изменения и актуальность','Документы могут расходиться с системой. Решение зависит от того, какая конфигурация является утверждённой целью.',[
 O(4),S('План, факт и основание изменения','Сначала устанавливают требуемую конфигурацию и разрешённое изменение; затем сравнивают фактическое состояние и документы. Нельзя автоматически переписывать паспорт под случайно обнаруженную настройку.','Если фактический адрес ошибочен, исправляют систему. Если изменение согласовано и выполнено, актуализируют документы и подтверждают результат. Различие предотвращает превращение дефекта в новую «норму» только из-за записи в паспорте.'),E('Одна разница — два решения','Паспорт: .20, фактически: .30. Случай A: переход на .30 согласован — обновляют документы после проверки. Случай B: утверждён .20, .30 возник ошибочно — восстанавливают требуемую конфигурацию.','Одинаковые числа не определяют решение без основания. В обоих случаях фиксируют причину, исполнителя и сквозную проверку. Планируемый переход ещё не разрешает помечать его выполненным.')],Check('Фактический адрес отличается от паспорта. Какое первое основание нужно?', ['Какой адрес красивее','Какая конфигурация утверждена и было ли разрешённое изменение','Случайный ответ ping'],1,'Решение о правке документа или системы зависит от целевого состояния и основания изменения.'),'Актуализация опирается на утверждённую цель, факт и подтверждённое выполнение.'),
Q('usability','Проверка комплектности действием','Наличие файлов не доказывает пригодность комплекта. Завершим попыткой найти объект и выполнить процедуру по документам.',[
 O(5),S('Доступность и разделение секретов','Документы должны быть доступны нужной роли, иметь ответственного и понятный статус. Пароли, токены и закрытые ключи не помещают в широко распространяемый паспорт; доступ к ним организуют отдельно по принятому порядку.','Сотруднику нужна инструкция получения разрешённого доступа, но это не означает публикацию секрета в учебной схеме. Проверьте, что ссылки ведут к актуальному документу, а резервная смена может получить нужные сведения.'),E('Приёмка комплекта','Другому сотруднику дают паспорт, схему и инструкцию для учебного узла. Он должен найти устройство, сопоставить порт, выполнить читающую проверку и объяснить результат. Неописанная подготовка считается выявленным пробелом.','Если автор документа стоит рядом и подсказывает каждый шаг, самостоятельная воспроизводимость не проверена. Сначала фиксируют, где процедура остановилась, затем исправляют соответствующее место и повторяют попытку.')],Check('Все файлы есть, но без автора нельзя найти нужный порт. Каков результат?', ['Комплект полностью пригоден','Наличие подтверждено; применимость не подтверждена, нужна доработка схемы','Нужно добавить ещё одну обложку'],1,'Цель документации — позволить выполнить действие; число файлов этого не доказывает.'),'Комплектность подтверждают поиском объектов и выполнением описанных процедур.')
],[('Почему нельзя всегда исправлять паспорт под фактический адрес?','Факт может быть ошибкой; сначала нужна утверждённая целевая конфигурация.'),('Чем структурная схема отличается от схемы соединений?','Первая показывает роли, вторая конкретизирует порты и линии для воспроизведения подключения.'),('Как обнаружить скрытую подготовку в инструкции?','Дать её другому исполнителю в заявленном исходном состоянии и зафиксировать первое невыполнимое действие.')],H('Паспорт DB-01 указывает адрес .20, фактически .30. Подготовьте два решения: утверждён переход на .30; утверждён .20 и обнаружена ошибочная настройка.','Для каждого случая определите, что менять, какие документы затрагиваются и чем подтвердить завершение.','Сдайте две короткие записи изменения с основанием и конечной проверкой.','При согласованном .30 обновляют взаимосвязанные документы после проверки факта; при целевом .20 исправляют конфигурацию и проверяют доступ и предметную операцию.'))
